INSERT INTO sparse_row_formats SELECT
        number,
        if(cityHash64(number, 1) % 50 = 0, cityHash64(number, 101) % 1000000, 0),
        if(cityHash64(number, 2) % 50 = 0, cityHash64(number, 102) % 1000000, 0),
        if(cityHash64(number, 3) % 50 = 0, cityHash64(number, 103) % 1000000, 0),
        if(cityHash64(number, 4) % 50 = 0, cityHash64(number, 104) % 1000000, 0),
        if(cityHash64(number, 5) % 50 = 0, cityHash64(number, 105) % 1000000, 0),
        if(cityHash64(number, 6) % 50 = 0, cityHash64(number, 106) % 1000000, 0),
        if(cityHash64(number, 7) % 50 = 0, cityHash64(number, 107) % 1000000, 0),
        if(cityHash64(number, 8) % 50 = 0, cityHash64(number, 108) % 1000000, 0),
        if(cityHash64(number, 9) % 50 = 0, cityHash64(number, 109) % 1000000, 0),
        if(cityHash64(number, 10) % 50 = 0, cityHash64(number, 110) % 1000000, 0),
        if(cityHash64(number, 11) % 50 = 0, cityHash64(number, 111) % 1000000, 0),
        if(cityHash64(number, 12) % 50 = 0, cityHash64(number, 112) % 1000000, 0),
        if(cityHash64(number, 13) % 50 = 0, cityHash64(number, 113) % 1000000, 0),
        if(cityHash64(number, 14) % 50 = 0, cityHash64(number, 114) % 1000000, 0),
        if(cityHash64(number, 15) % 50 = 0, cityHash64(number, 115) % 1000000, 0),
        if(cityHash64(number, 16) % 50 = 0, cityHash64(number, 116) % 1000000, 0),
        if(cityHash64(number, 17) % 50 = 0, concat('v', toString(cityHash64(number, 117) % 100000)), ''),
        if(cityHash64(number, 18) % 50 = 0, concat('v', toString(cityHash64(number, 118) % 100000)), ''),
        if(cityHash64(number, 19) % 50 = 0, concat('v', toString(cityHash64(number, 119) % 100000)), ''),
        if(cityHash64(number, 20) % 50 = 0, concat('v', toString(cityHash64(number, 120) % 100000)), '')
    FROM numbers(2000000)
